sp_widget.client_script:
function($scope, $rootScope, spUtil, $timeout) {
  $scope.anoAnteriorSelecionado = null;
  $scope.dadosAnoAnterior = null;
  $scope.isFadingAnoAnterior = false;

  function carregarDadosAnoAnterior(anoFiltro) {
    $scope.isFadingAnoAnterior = true;

    if (anoFiltro) {
      var anoAnterior = parseInt(anoFiltro, 10) - 1;
      $scope.anoAnteriorSelecionado = anoAnterior;

      var params = { filtro_ano: anoAnterior };

      spUtil.get('rcl_total_ano_card_2', params).then(function(respAnoAnterior) {
        if (respAnoAnterior.data && respAnoAnterior.data.dados && respAnoAnterior.data.dados.length > 0) {
          $scope.dadosAnoAnterior = respAnoAnterior.data.dados[0];
        } else {
          $scope.dadosAnoAnterior = null;
        }
        $timeout(function() {
          $scope.isFadingAnoAnterior = false;
        }, 500);
      });

    } else {
      spUtil.get('rcl_total_ano_card_2').then(function(response) {
        var ultimoAno = null;

        if (response.data && response.data.dados && response.data.dados.length > 0) {
          ultimoAno = response.data.dados[0].ano;
        }

        if (ultimoAno) {
          var anoAnterior = parseInt(ultimoAno, 10) - 1;
          $scope.anoAnteriorSelecionado = anoAnterior;

          var params = { filtro_ano: anoAnterior };

          spUtil.get('rcl_total_ano_card_2', params).then(function(respAnoAnterior) {
            if (respAnoAnterior.data && respAnoAnterior.data.dados && respAnoAnterior.data.dados.length > 0) {
              $scope.dadosAnoAnterior = respAnoAnterior.data.dados[0];
            } else {
              $scope.dadosAnoAnterior = null;
            }
            $timeout(function() {
              $scope.isFadingAnoAnterior = false;
            }, 300);
          });

        } else {
          $scope.dadosAnoAnterior = null;
          $scope.anoAnteriorSelecionado = null;
          $scope.isFadingAnoAnterior = false;
        }
      });
    }
  }

  carregarDadosAnoAnterior(null);

  $rootScope.$on('anoSelecionado', function(evt, anoSelecionado) {
    carregarDadosAnoAnterior(anoSelecionado);
  });
}

sp_widget.css:
div, h2 {
   font-family: 'Roboto Flex', sans-serif;
 }

 .report-widget {
   border-radius: 12px;
   box-shadow: 0 2px 6px rgba(0, 0, 0, 0.08);
   background-color: #fff;
   margin-top: 24px;
   overflow: hidden;
   display: flex;
   flex-direction: column;
   font-family: 'Roboto Flex', sans-serif;
   /* Transição para o fade + movimento vertical */
   opacity: 1;
   visibility: visible;
   transform: translateY(0);
   transition: opacity 0.5s ease-in-out, transform 0.5s ease-in-out, visibility 0.5s ease-in-out;
 }

 .report-widget.panel.fade-out {
   opacity: 0;
   visibility: hidden;
   transform: translateY(20px);
 }

 /* --- Media Queries para Responsividade --- */

 /* Telas Pequenas (Mobile S, M, L - até 767px) */
 @media (max-width: 767px) {
   .report-widget {
     margin-top: 1rem;
   }
   .panel-title {
     font-size: 1.5rem;
   }
   .panel-body {
     padding: 8px;
   }
 }

 /* Tablets (768px até 1023px) */
 @media (min-width: 768px) and (max-width: 1023px) {
   .report-widget {
     margin-top: 1.5rem;
   }
   .panel-title {
     font-size: 1.1rem;
   }
 }

 /* Laptops e Telas Maiores (1024px em diante) */
 @media (min-width: 1024px) {
   .report-widget {
     margin-top: 24px; /* Valor original */
   }
   .panel-title {
     font-size: 1.5em; /* Valor original */
   }
 }

 /* Ajustes para dispositivos muito largos (1280px em diante) */
 @media (min-width: 1280px) {
   .panel-heading {
     padding: 14px 18px;
   }
   .panel-body {
     padding: 20px;
   }
 }

 /* Ajustes Surface Duo (540x720) */
 @media (width: 540px) and (height: 720px) {
   .report-widget {
     margin-top: 1.2rem;
   }
   .panel-title {
     font-size: 1rem;
   }
 }

 /* Ajustes Galaxy Z Fold 5 (max-width: 350px) */
 @media (max-width: 350px) {
   .panel-title {
     font-size: 0.9rem;
   }
   .panel-body {
     padding: 6px;
   }
 }

 .panel-heading {
   font-family: 'Roboto Flex', sans-serif;
   background-color: #e0e0e0; /* fundo cinza claro */
   padding: 12px 16px;
   border-bottom: 1px solid #ccc;
   border-top-left-radius: 12px;
   border-top-right-radius: 12px;
 }

 .panel-title {
   font-family: 'Roboto Flex', sans-serif;
   margin: 0;
   font-size: 1.2em;
   color: #333;
   text-align: center;
 }

 .panel-body {
   font-family: 'Roboto Flex', sans-serif;
   padding: 16px;
   flex: 1;
   width: 100%;
 }

 /* Transição da mensagem "Nenhum dado" */
 .mensagem {
   opacity: 0;
   visibility: hidden;
   transform: translateY(20px);
   transition: opacity 0.5s ease-in-out, visibility 0.5s ease-in-out, transform 0.5s ease-in-out;
   height: 0;
   overflow: hidden;
 }

 .mensagem.show {
   opacity: 1;
   visibility: visible;
   transform: translateY(0);
   height: auto;
 }

sp_widget.script:
(function() {
	function formatarNumero(valor, divisor, sufixo) {
		var resultado = (valor / divisor);
		resultado = resultado.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
		return resultado + ' ' + sufixo;
	}


  // input.filtro_ano pode estar vazio ou indefinido
  var anoFiltrado = input && input.filtro_ano ? input.filtro_ano : null;

  if (!anoFiltrado) {
    // Buscar o último ano da tabela
    var grAno = new GlideRecord('x_sded9_portal_t_0_u_rreo');
    grAno.orderByDesc('u_ano');
    grAno.setLimit(1);
    grAno.query();

    if (!grAno.next()) {
      data.temDado = false;
      data.ano = null;
      data.dados = [];
      return;
    }

    anoFiltrado = grAno.getValue('u_ano');
  }

  // Soma do anoFiltrado
  var grSoma = new GlideRecord('x_sded9_portal_t_0_u_rreo');
  grSoma.addQuery('u_ano', anoFiltrado);
  grSoma.query();

  var soma = 0;
  while (grSoma.next()) {
    soma += parseFloat(grSoma.getValue('rreo_according_to_lrf_fiscal_responsibility_law_2')) || 0;
  }

  // Aqui a diferença: soma >= 0 considera zero como dado válido
  if (soma >= 0) {
    var valorFormatado = (soma >= 1) ? formatarNumero(soma, 1, '') : formatarNumero(soma, 1, '');
    data.temDado = true;
    data.valorSoma = soma;
    data.valorSomaFormatado = valorFormatado;
    data.ano = anoFiltrado;
    data.dados = [{
      ano: anoFiltrado,
      valorSoma: soma,
      valorSomaFormatado: valorFormatado,
      temDado: true
    }];
  } else {
    data.temDado = false;
    data.ano = anoFiltrado;
    data.dados = [{
      ano: anoFiltrado,
      valorSoma: 0,
      valorSomaFormatado: '0',
      temDado: false
    }];
  }
})();
